#include <string.h>

int main(void) {
    char word[] = "{x}";
    char copy[30];

    strcpy(copy, word);
    strcat(copy, "{y}");

    printf("%s\n", copy);
    printf("%d\n", (int)strlen(copy));
    return 0;
}
